<script lang="ts">
 import {onMount} from 'svelte';import {Button} from '$lib/components/ui/button';import {Film,ArrowUpRight} from '@lucide/svelte';import {request} from '../api';import {appendUnique,requestGate} from '../viewing/feed-state';
 let {user}:{user:any}=$props();let items=$state<any[]>([]),cursor=$state(''),status=$state(''),format=$state(''),visibility=$state(''),busy=$state(false),error=$state('');const gate=requestGate();
 onMount(()=>{void load();return()=>{gate.next();};});
 async function load(more=false){const sequence=gate.next();busy=true;error='';try{const result=await request(`/channel/videos?${new URLSearchParams({status,format,visibility,...(more&&cursor?{cursor}:{})})}`);if(!gate.current(sequence))return;items=more?appendUnique(items,result.items):result.items;cursor=result.next_cursor||'';}catch(e){if(gate.current(sequence))error=(e as Error).message;}finally{if(gate.current(sequence))busy=false;}}
</script>
<div class="page-heading"><h1>My content</h1><p>Manage your videos, visibility and viewing access.</p></div>
<div class="content-actions"><Button href="/studio/videos">Choose a finished video</Button><Button variant="outline" href="/studio/upload">Upload video</Button><a href={`/channels/${user.handle}`}>Public profile<ArrowUpRight class="size-4"/></a></div>
<div class="content-filters"><label>Status<select bind:value={status} onchange={()=>void load()}><option value="">All statuses</option><option value="draft">Draft</option><option value="processing">Processing</option><option value="published">Published</option><option value="failed">Failed</option><option value="blocked">Blocked</option></select></label><label>Format<select bind:value={format} onchange={()=>void load()}><option value="">All formats</option><option value="standard">Videos</option><option value="short">Shorts</option></select></label><label>Visibility<select bind:value={visibility} onchange={()=>void load()}><option value="">All visibility</option><option value="public">Public</option><option value="unlisted">Unlisted</option><option value="private">Private</option></select></label></div>
{#if error}<div class="cloud-alert" role="alert">{error}<Button variant="ghost" onclick={()=>load()}>Try again</Button></div>{/if}
{#if busy&&!items.length}<p role="status">Loading your content…</p>{:else if !items.length}<div class="cloud-empty compact"><Film class="size-8"/><h2>{status||format||visibility?'No matching videos':'No publications yet'}</h2><p>{status||format||visibility?'Try another status or format.':'Publish a finished Studio output or upload a video to get started.'}</p></div>{:else}<div class="content-list" aria-busy={busy}>{#each items as video(video.id)}<article><Film class="size-5"/><div><h2>{video.title}</h2><p>{video.format==='short'?'Short':'Video'} · {video.visibility} · {video.audience==='members'?'Premium':'Free'} · {video.status}</p>{#if video.status==='failed'}<p>Processing failed. Open the publication to review or retry.</p>{/if}</div><Button variant="outline" size="sm" href={`/studio/publish?video=${video.id}`}>Manage<span class="sr-only"> {video.title}</span></Button>{#if video.status==='published'}<a class="watch" href={`/${video.format==='short'?'shorts':'watch'}/${video.id}`}>Watch<ArrowUpRight class="size-3.5"/></a>{/if}</article>{/each}</div>{/if}
{#if cursor}<Button variant="outline" disabled={busy} onclick={()=>load(true)}>{busy?'Loading…':'Load more videos'}</Button>{/if}
<style>.content-actions{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:28px}.content-actions>a{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted-foreground);margin-left:auto}.content-filters{display:flex;flex-wrap:wrap;gap:20px;margin-bottom:24px}.content-filters label{display:grid;gap:8px;min-width:150px}.content-list{margin-bottom:24px}.content-list article{display:flex;align-items:center;gap:18px;padding:20px 0;border-top:1px solid var(--border)}.content-list article>div{flex:1;min-width:0}.content-list h2{font-size:14px;font-weight:550;overflow-wrap:anywhere}.content-list p{font-size:12px;color:var(--muted-foreground);margin-top:8px}.watch{display:flex;align-items:center;gap:5px;font-size:12px;color:var(--muted-foreground)}@media(max-width:600px){.content-actions>a{margin-left:0;min-height:44px}.content-filters{gap:12px}.content-filters label{min-width:0;flex:1}.content-list article{display:grid;grid-template-columns:1fr auto;gap:12px}.content-list article> :global(svg){display:none}.content-list article>div{grid-column:1/-1}.watch{min-height:44px;justify-content:flex-end}.content-list :global(button),.content-list :global(a[data-slot=button]){min-height:44px}}</style>
